"""Ed25519 signing of `latest.json`.

Rules:
* the private key is generated by the operator (``python -m mxstudio.update keygen``) and
  lives only in the CI secret ``MXS_UPDATE_SIGNING_KEY`` — never in the repository, never
  printed by this module;
* the app trusts only public keys embedded at build time (``trust.json``), addressed by
  ``key_id = sha256(raw public key)[:16]``;
* verification fails closed: no signature, unknown key, wrong algorithm, or any byte of the
  signed body changed → :class:`SignatureError`.

Key encoding: base64 of the raw 32-byte key (fits a GitHub secret on one line). PEM PKCS#8
private keys are accepted too.
"""
from __future__ import annotations

import base64
import binascii
import hashlib
from typing import Any

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey, Ed25519PublicKey

from .errors import SignatureError
from .manifest import canonical_bytes

ALG = "Ed25519"


def _raw_public(key: Ed25519PublicKey) -> bytes:
    return key.public_bytes(serialization.Encoding.Raw, serialization.PublicFormat.Raw)


def generate_keypair() -> tuple[str, str]:
    """Return ``(private_b64, public_b64)``. The caller must store the private half safely."""
    private = Ed25519PrivateKey.generate()
    raw_private = private.private_bytes(serialization.Encoding.Raw, serialization.PrivateFormat.Raw,
                                        serialization.NoEncryption())
    return base64.b64encode(raw_private).decode("ascii"), base64.b64encode(_raw_public(private.public_key())).decode("ascii")


def load_private(text: str) -> Ed25519PrivateKey:
    text = (text or "").strip()
    if not text:
        raise SignatureError("no_signing_key", "مفتاح التوقيع مش موجود", "No signing key was provided")
    if text.startswith("-----BEGIN"):
        key = serialization.load_pem_private_key(text.encode("ascii"), password=None)
        if not isinstance(key, Ed25519PrivateKey):
            raise SignatureError("bad_signing_key", "المفتاح مش Ed25519", "The PEM key is not Ed25519")
        return key
    try:
        raw = base64.b64decode(text, validate=True)
    except (binascii.Error, ValueError) as exc:
        raise SignatureError("bad_signing_key", "مفتاح التوقيع مش base64 سليم", "Signing key is not valid base64") from exc
    if len(raw) != 32:
        raise SignatureError("bad_signing_key", "مفتاح التوقيع لازم يكون 32 بايت", "Signing key must be 32 raw bytes")
    return Ed25519PrivateKey.from_private_bytes(raw)


def load_public(b64: str) -> Ed25519PublicKey:
    try:
        raw = base64.b64decode((b64 or "").strip(), validate=True)
    except (binascii.Error, ValueError) as exc:
        raise SignatureError("bad_public_key", "المفتاح العام مش base64 سليم", "Public key is not valid base64") from exc
    if len(raw) != 32:
        raise SignatureError("bad_public_key", "المفتاح العام لازم 32 بايت", "Public key must be 32 raw bytes")
    return Ed25519PublicKey.from_public_bytes(raw)


def key_id(public_b64: str) -> str:
    return hashlib.sha256(_raw_public(load_public(public_b64))).hexdigest()[:16]


def public_from_private(private_text: str) -> str:
    return base64.b64encode(_raw_public(load_private(private_text).public_key())).decode("ascii")


def sign_manifest(manifest: dict[str, Any], private_text: str) -> dict[str, Any]:
    """Return a copy of ``manifest`` carrying an Ed25519 signature over its canonical body."""
    private = load_private(private_text)
    public_b64 = base64.b64encode(_raw_public(private.public_key())).decode("ascii")
    signature = private.sign(canonical_bytes(manifest))
    signed = {k: v for k, v in manifest.items() if k != "signature"}
    signed["signature"] = {"alg": ALG, "key_id": key_id(public_b64),
                           "value": base64.b64encode(signature).decode("ascii")}
    return signed


def verify_manifest(manifest: dict[str, Any], trusted_keys: dict[str, str] | list[str]) -> str:
    """Verify the signature against embedded public keys; return the key_id that signed it."""
    if isinstance(trusted_keys, (list, tuple)):
        trusted = {key_id(k): k for k in trusted_keys}
    else:
        trusted = dict(trusted_keys or {})
    if not trusted:
        raise SignatureError("no_trusted_key",
                             "النسخة دي مفيهاش مفتاح عام للتحديثات، فمش هنثبّت أي تحديث تلقائي.",
                             "This build embeds no update public key, so no update is trusted.")
    sig = manifest.get("signature") if isinstance(manifest, dict) else None
    if not isinstance(sig, dict) or sig.get("alg") != ALG or not sig.get("value"):
        raise SignatureError("unsigned", "ملف التحديث مش موقّع.", "The update manifest is not signed.")
    kid = sig.get("key_id")
    if kid not in trusted:
        raise SignatureError("unknown_key", "ملف التحديث موقّع بمفتاح مش معروف.",
                             "The update manifest is signed by an unknown key.")
    try:
        raw_sig = base64.b64decode(sig["value"], validate=True)
        load_public(trusted[kid]).verify(raw_sig, canonical_bytes(manifest))
    except (InvalidSignature, binascii.Error, ValueError) as exc:
        raise SignatureError("bad_signature",
                             "توقيع ملف التحديث مش مطابق — الملف اتغيّر بعد التوقيع، ومش هنستخدمه.",
                             "The update manifest signature does not match; it was changed after signing.") from exc
    return kid
